/**
 * Wire up "Request access" buttons in the catalog.
 *
 * @module local_sentientia_request/request_button
 *
 * Build note (2026-06-11, WF-019): hand-rolled from amd/src/request_button.js
 * to classic AMD because no grunt build is checked in (tree-wide CRLF eslint
 * noise blocks `grunt amd` — same practice as my_requests.min.js). Keep in
 * sync with the src on every change.
 */
define("local_sentientia_request/request_button",
    ["core/ajax", "core/notification", "core/modal_events"],
    function(Ajax, Notification, ModalEvents) {

    var createSaveCancelModal = function(spec) {
        return new Promise(function(resolve, reject) {
            // WF-024: 5.2 SAVE_CANCEL modal is core/modal_save_cancel. The old
            // core/modal Modal.create({modalType:"SAVE_CANCEL"}) built a base
            // modal with an EMPTY footer (no Save/Cancel) — request unsubmittable.
            var viaFactory = function() {
                require(["core/modal_factory"], function(ModalFactory) {
                    ModalFactory.create({type: ModalFactory.types.SAVE_CANCEL, title: spec.title, body: spec.body})
                        .then(resolve).catch(reject);
                }, reject);
            };
            require(["core/modal_save_cancel"], function(ModalSaveCancel) {
                if (ModalSaveCancel && typeof ModalSaveCancel.create === "function") {
                    ModalSaveCancel.create({title: spec.title, body: spec.body})
                        .then(resolve).catch(reject);
                    return;
                }
                viaFactory();
            }, viaFactory);
        });
    };

    var init = function() {
        document.addEventListener("click", async function(e) {
            var btn = e.target.closest('[data-action="request-course"]');
            if (!btn) {
                return;
            }
            e.preventDefault();
            var courseid = parseInt(btn.dataset.courseid, 10);
            // Escape: course names are user-controlled data interpolated
            // into modal HTML (WF-019 hardening, mirrors decide.js).
            var coursename = String(btn.dataset.coursename || "this course").replace(/[&<>"']/g, function(c) {
                return {"&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;"}[c];
            });
            if (!courseid) {
                return;
            }

            var modal = await createSaveCancelModal({
                title: "Request enrolment",
                body: "<p>Requesting access to <strong>" + coursename + "</strong>.</p>" +
                    "<p class=\"text-muted small\">Your request will be routed to your manager (if assigned) " +
                    "or course owner. SLA: 48 hours.</p>" +
                    "<div class=\"mb-2\">" +
                    "<label class=\"form-label\">Reason (min 20 chars)</label>" +
                    "<textarea id=\"request_reason\" class=\"form-control\" rows=\"4\" " +
                    "placeholder=\"Why do you need this course?\"></textarea>" +
                    "<small class=\"text-muted\">e.g. &quot;Required for new role in operations team.&quot;</small>" +
                    "</div>"
            });

            modal.getRoot().on(ModalEvents.save, function() {
                var reason = document.getElementById("request_reason").value || "";
                if (reason.trim().length < 20) {
                    Notification.alert("Reason too short",
                        "Please give at least 20 characters explaining why.");
                    return;
                }
                Ajax.call([{
                    methodname: "local_sentientia_request_submit",
                    args: {courseid: courseid, reason: reason.trim()}
                }])[0].then(function() {
                    btn.disabled = true;
                    btn.textContent = "Requested";
                    Notification.addNotification({
                        message: "Request submitted successfully.",
                        type: "success"
                    });
                    return;
                }).catch(Notification.exception);
            });

            modal.show();
        });
    };

    return {init: init};
});
